{"path": "textutils.py", "content": "import re
from collections import Counter

# A word is a run of letters, digits and apostrophes.
_WORD_RE = re.compile(r"(?:[^\W_]|')+")


def words(text):
    return text.split()


def word_count(text):
    """Map lower-cased words to their counts, ignoring punctuation."""
    return dict(Counter(m.lower() for m in _WORD_RE.findall(text)))
