from textutils import words, word_count


class T(unittest.TestCase):
    def test_words(self):
        self.assertEqual(words('a b'), ['a', 'b'])

    def test_word_count(self):
        self.assertEqual(
            word_count("Hello, hello! It's 2 o'clock; it's late-ish."),
            {'hello': 2, "it's": 2, '2': 1, "o'clock": 1, 'late': 1, 'ish': 1},
        )

    def test_word_count_empty(self):
        self.assertEqual(word_count(''), {})
        self.assertEqual(word_count('...!?'), {})

    def test_word_count_underscore_is_separator(self):
        self.assertEqual(word_count('a_b A'), {'a': 2, 'b': 1})


if __name__ == '__main__':
    unittest.main()
"}
